def isok(x):
    x = str(x)
    for i in range(len(x)//2):
        if x[i] != x[-i-1]:
            return False
    return True

n = int(input())
ans = 0
i = 1
while i**3 <= n:
    if isok(i**3):
        ans = i**3
    i += 1
print(ans)
